import 'package:jnigen/jnigen.dart';

void main(List<String> args) async {
  final generator = JniGenerator(
    input: Input(
      classes: ['com.example.MyClass'],
    ),
    output: Output(
      dart: DartOutput(
        path: Uri.parse('lib/src/generated_bindings.dart'),
      ),
    ),
  );
  await generator.generate();
}
